def min_partition_difference(n, weights):
    total_sum = sum(weights)
    target = total_sum // 2
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: zero sum is always possible with zero elements
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if weights[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - weights[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the largest j such that dp[n][j] is True
    for j in range(target, -1, -1):
        if dp[n][j]:
            return total_sum - 2 * j

