def process_input(input_list):
    processed_list = []
    for x in input_list:
        if -50 <= x <= -1:
            processed_list.append(100 - x)
        elif x == 0:
            processed_list.append("ZERO")
        elif 1 <= x <= 50:
            processed_list.append(x * 2)
        else:
            processed_list.append(x)
    return processed_list

