from collections import defaultdict

def groupBy2(l, key):
    ans = defaultdict(list)
    for elem in l:
        ans[key(elem)].append(elem)
    return dict(ans)

def minSessions(tasks, sessionTime):
    def backtrack(index, sessions):
        if index == len(tasks):
            return len(sessions)

        for i in range(len(sessions)):
            if sessions[i] + tasks[index] <= sessionTime:
                sessions[i] += tasks[index]
                result = backtrack(index + 1, sessions)
                sessions[i] -= tasks[index]
                if result != float('inf'):
                    return result

        # Start a new session
        return backtrack(index + 1, sessions + [tasks[index]])

    tasks.sort(reverse=True)
    return backtrack(0, [])

# Test cases
print(minSessions([1, 2, 3, 4], 5))  # Output: 2
print(minSessions([3, 1, 4, 1, 5, 9, 2, 6], 10))  # Output: 3
print(minSessions([10, 20, 30], 25))  # Output: 3

from typing import List

def find_student_by_mark(marks: List[int], target_mark: int) -> int:
    for i, mark in enumerate(marks):
        if mark == target_mark:
            return i
    return -1

